array.string:
export PATH="$HOME/.nvm/versions/node/v24.15.0/bin:/Library/Frameworks/Python.framework/Versions/3.14/bin:/usr/local/bin:/usr/bin:/bin" DIR="$HOME/Desktop/벌크농부/00_벌크농부 마케팅 에이전트팀" CFG="$HOME/.config/bulkfarmer/telegram.env"
[ -f "$CFG" ] && source "$CFG" notify() { [ -z "$TELEGRAM_BOT_TOKEN" ] && return curl -s -X POST "https://api.telegram.org/bot$TELEGRAM_BOT_TOKEN/sendMessage" \ --data-urlencode "chat_id=$TELEGRAM_CHAT_ID" --data-urlencode "text=$1" >/dev/null }
cd "$DIR" || { notify "⚠️ 주간 리포트 실패: 프로젝트 폴더에 접근할 수 없습니다."; exit 1; }
PROMPT=$(cat _analytics/weekly_report_prompt.txt 2>&1) || { notify "⚠️ 주간 리포트 실패: 프롬프트 파일을 읽지 못했습니다. $PROMPT
시스템 설정 → 개인정보 보호 및 보안 → 전체 디스크 접근 권한에 /bin/zsh 가 등록되어 있는지 확인하세요." exit 1 }
command -v claude >/dev/null || { notify "⚠️ 주간 리포트 실패: claude CLI를 찾을 수 없습니다 (PATH 문제)."; exit 1; } command -v yt-dlp >/dev/null || notify "⚠️ 경고: yt-dlp를 찾을 수 없습니다. 수집이 실패할 수 있습니다."
# 맥이 깨어난 직후에는 네트워크가 아직 안 올라와 있다. 2026-08-03 아침에 이 작업과 # 주간 리포트가 같은 이유(ENOTFOUND / Connection closed)로 죽었다. # API에 닿을 때까지 최대 10분 기다린다. 그래도 안 되면 조용히 끝내지 않고 알린다. for i in $(seq 1 40); do curl -s -m 5 -o /dev/null https://api.anthropic.com/ && break sleep 15 done curl -s -m 5 -o /dev/null https://api.anthropic.com/ || { notify "⚠️ 주간 리포트: 10분을 기다려도 네트워크에 연결되지 않았습니다"; exit 1; } # 종료 코드는 믿을 수 없다. 2026-08-03에 코드 0으로 끝났는데 리포트가 없었다 # (서브에이전트에 위임하고 턴을 끝내버렸다). 성공 판정은 **결과 파일**로 한다. OUT="_analytics/$(date +%F)_channel_report.md" RC=1 for TRY in 1 2; do [ -s "$OUT" ] && { RC=0; break; } [ $TRY -gt 1 ] && sleep 60 claude -p "$PROMPT" --model claude-sonnet-5 --permission-mode acceptEdits \ --allowedTools Bash Read Write Edit Glob Grep WebSearch WebFetch [ -s "$OUT" ] && { RC=0; break; } echo "[$(date +%T)] 리포트 시도 $TRY 실패 — 결과 파일 없음" >&2 done
if [ $RC -ne 0 ]; then notify "⚠️ 주간 리포트 실패 (종료 코드 $RC) 마지막 오류: $(tail -c 400 _analytics/cron.err.log 2>/dev/null)" fi exit $RC
